-- Migration 123: Compiled knowledge briefs.
--
-- A brief is the machine-maintained "world model" for a scope: a markdown
-- synthesis of that scope's ranked claims, regenerated by the nightly
-- knowledge-weaver job whenever the underlying claims change. Briefs are what
-- make accumulated knowledge CHEAP to load — the chat agent injects the
-- workspace brief into its system prompt, the MCP server exposes briefs as
-- resources, and package exports lead with them.
--
-- Scopes:
--   workspace — one per workspace (scope_id NULL)
--   project   — one per project with enough claims
--   package   — one per knowledge package (migration 124)
--
-- Writes happen only from service-role jobs (no INSERT/UPDATE policies for
-- authenticated). Members can read briefs for their workspace.

CREATE TABLE IF NOT EXISTS public.knowledge_brief (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id UUID NOT NULL REFERENCES public.workspace(id) ON DELETE CASCADE,
  scope_type TEXT NOT NULL CHECK (scope_type IN ('workspace', 'project', 'package')),
  scope_id UUID,
  content TEXT NOT NULL,
  claim_count INTEGER NOT NULL DEFAULT 0,
  -- Hash of the input claim set (ids + updated_at). Lets the generator skip
  -- regeneration when nothing changed.
  source_fingerprint TEXT,
  generated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE NULLS NOT DISTINCT (workspace_id, scope_type, scope_id)
);

CREATE INDEX IF NOT EXISTS idx_knowledge_brief_workspace
  ON public.knowledge_brief (workspace_id, scope_type);

ALTER TABLE public.knowledge_brief ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS knowledge_brief_select ON public.knowledge_brief;
CREATE POLICY knowledge_brief_select ON public.knowledge_brief
  FOR SELECT USING (public.is_workspace_member(workspace_id));
